[CmdletBinding()]
param(
 [Parameter(Mandatory)][string]$PayloadRoot,
 [Parameter(Mandatory)][string]$OutputRoot,
 [ValidateRange(15,300)][int]$ApplicationSmokeTimeoutSeconds=300,
 [switch]$SkipNativeLoad,
 [switch]$SkipApplicationSmoke
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Get-ContentHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$PayloadRoot=[IO.Path]::GetFullPath($PayloadRoot);$OutputRoot=[IO.Path]::GetFullPath($OutputRoot)
if(-not(Test-Path $PayloadRoot -PathType Container)){throw "PayloadRoot is missing: $PayloadRoot"}
if(Test-Path $OutputRoot){throw "Refusing to overwrite diagnostic output: $OutputRoot"}
New-Item -ItemType Directory -Path $OutputRoot|Out-Null
$failures=[Collections.Generic.List[string]]::new();$observed=[ordered]@{}
try {
 $os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$cp=Get-CimInstance Win32_ComputerSystemProduct;$net=@(Get-NetAdapter -ErrorAction Stop|Where-Object Status -eq 'Up')
 $observed=[ordered]@{manufacturer=[string]$cs.Manufacturer;machineUuid=([string]$cp.UUID).ToLowerInvariant();osCaption=[string]$os.Caption;osBuild=[string]$os.BuildNumber;installTimeUtc=([DateTime]$os.InstallDate).ToUniversalTime().ToString('O');installAgeHours=[math]::Round(([DateTimeOffset]::UtcNow-[DateTimeOffset]$os.InstallDate).TotalHours,3);activeNetworkAdapterCount=$net.Count}
 $exe=Join-Path $PayloadRoot 'GraphReader.App.exe';$mode=Join-Path $PayloadRoot 'portable.mode';$dll=@(Get-ChildItem -LiteralPath $PayloadRoot -Filter OpenCvSharpExtern.dll -Recurse -File);$models=@(Get-ChildItem -LiteralPath $PayloadRoot -Recurse -File|Where-Object{$_.Extension -in @('.onnx','.param','.bin')})
 if(-not(Test-Path $exe -PathType Leaf)){$failures.Add('GraphReader.App.exe is missing.')};if(-not(Test-Path $mode -PathType Leaf)){$failures.Add('portable.mode is missing.')};if($dll.Count -ne 1){$failures.Add("Expected one OpenCvSharpExtern.dll, found $($dll.Count).")};if($models.Count -ne 0){$failures.Add("Expected model-free payload, found $($models.Count) model files.")}
 $portablePreflightPassed=(Test-Path $exe -PathType Leaf) -and (Test-Path $mode -PathType Leaf) -and $dll.Count -eq 1 -and $models.Count -eq 0
 $preExecutableSha256=if(Test-Path $exe -PathType Leaf){Get-ContentHash $exe}else{$null};$preOpenCvSha256=if($dll.Count -eq 1){Get-ContentHash $dll[0].FullName}else{$null}
 $native=[ordered]@{attempted=$false;succeeded=$false;skipped=[bool]$SkipNativeLoad;sha256=$preOpenCvSha256;error=$null;flags='LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR|LOAD_LIBRARY_SEARCH_DEFAULT_DIRS'}
 if(-not $SkipNativeLoad -and $dll.Count -eq 1){try {if($null -eq ('GraphReaderModelFreeDiagNative' -as [type])){Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class GraphReaderModelFreeDiagNative { [DllImport("kernel32",CharSet=CharSet.Unicode,SetLastError=true)] public static extern IntPtr LoadLibraryEx(string p, IntPtr reserved, uint flags); [DllImport("kernel32",SetLastError=true)] public static extern bool FreeLibrary(IntPtr p); }'};$native.attempted=$true;$m=[GraphReaderModelFreeDiagNative]::LoadLibraryEx($dll[0].FullName,[IntPtr]::Zero,[uint32]0x00001100);if($m -eq [IntPtr]::Zero){throw "Win32 error $([Runtime.InteropServices.Marshal]::GetLastWin32Error())"};$native.succeeded=[GraphReaderModelFreeDiagNative]::FreeLibrary($m);if(-not $native.succeeded){throw 'Loaded DLL could not be freed.'}}catch{$native.error=$_.Exception.Message;$failures.Add("OpenCV native load failed: $($native.error)")}}
 $smoke=[ordered]@{attempted=$false;skipped=[bool]$SkipApplicationSmoke;exitCode=$null;timedOut=$false;passed=$false}
 if(-not $SkipApplicationSmoke -and $portablePreflightPassed){try{$smoke.attempted=$true;$oldData=[Environment]::GetEnvironmentVariable('GRAPHREADER_DEV_PORTABLE_DATA_ROOT','Process');$oldEnhancement=[Environment]::GetEnvironmentVariable('GRAPHREADER_REALESRGAN_RUNTIME_ROOT','Process');$oldManifest=[Environment]::GetEnvironmentVariable('GRAPHREADER_REALESRGAN_MANIFEST_PATH','Process');$oldPdfium=[Environment]::GetEnvironmentVariable('GRAPHREADER_PDFIUM_APPROVAL_PATH','Process');try{[Environment]::SetEnvironmentVariable('GRAPHREADER_DEV_PORTABLE_DATA_ROOT',(Join-Path $OutputRoot 'Data'),'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_REALESRGAN_RUNTIME_ROOT',$null,'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_REALESRGAN_MANIFEST_PATH',$null,'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_PDFIUM_APPROVAL_PATH',$null,'Process');$p=$null;try{$p=Start-Process -FilePath $exe -ArgumentList '--portable-smoke' -WorkingDirectory $PayloadRoot -PassThru -WindowStyle Hidden;if(-not $p.WaitForExit($ApplicationSmokeTimeoutSeconds*1000)){$smoke.timedOut=$true;try{Stop-Process -Id $p.Id -Force -ErrorAction Stop}catch{$failures.Add("Timed-out smoke termination failed: $($_.Exception.Message)")};$failures.Add('Portable smoke timed out.')}else{$smoke.exitCode=$p.ExitCode;$smoke.passed=($p.ExitCode -eq 0);if(-not $smoke.passed){$failures.Add("Portable smoke exited $($p.ExitCode).")}}}finally{if($null -ne $p){try{if(-not $p.HasExited){Stop-Process -Id $p.Id -Force -ErrorAction Stop}}catch{$failures.Add("Unexpected smoke termination failed: $($_.Exception.Message)")}finally{$p.Dispose()}}}}finally{[Environment]::SetEnvironmentVariable('GRAPHREADER_DEV_PORTABLE_DATA_ROOT',$oldData,'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_REALESRGAN_RUNTIME_ROOT',$oldEnhancement,'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_REALESRGAN_MANIFEST_PATH',$oldManifest,'Process');[Environment]::SetEnvironmentVariable('GRAPHREADER_PDFIUM_APPROVAL_PATH',$oldPdfium,'Process')}}catch{$failures.Add("Portable smoke failed: $($_.Exception.Message)")}}
 $postExecutableSha256=if(Test-Path $exe -PathType Leaf){Get-ContentHash $exe}else{$null};$postOpenCvSha256=if($dll.Count -eq 1 -and(Test-Path $dll[0].FullName -PathType Leaf)){Get-ContentHash $dll[0].FullName}else{$null};if($preExecutableSha256 -ne $postExecutableSha256){$failures.Add('GraphReader.App.exe changed during diagnostic execution.')};if($preOpenCvSha256 -ne $postOpenCvSha256){$failures.Add('OpenCvSharpExtern.dll changed during diagnostic execution.')}
 $status=if($failures.Count){'fail'}elseif($SkipNativeLoad -or $SkipApplicationSmoke){'incomplete'}else{'pass'}
 [ordered]@{schema='graphreader.model-free-opencv-guest-diagnostic.v1';status=$status;observedAtUtc=[DateTimeOffset]::UtcNow.ToString('O');observedMachine=$observed;payload=[ordered]@{root=$PayloadRoot;executableSha256=[ordered]@{before=$preExecutableSha256;after=$postExecutableSha256};portableModePresent=(Test-Path $mode);openCvCandidateCount=$dll.Count;openCvSha256=[ordered]@{before=$preOpenCvSha256;after=$postOpenCvSha256};modelPayloadCount=$models.Count};nativeLoad=$native;applicationSmoke=$smoke;failures=@($failures);temporalLinkageClaimed=$false;releaseEvidence=$false}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $OutputRoot 'model-free-opencv-guest-diagnostic.json') -Encoding utf8
 if($status -ceq 'pass'){exit 0};if($status -ceq 'incomplete'){exit 3};exit 2
}catch{[ordered]@{schema='graphreader.model-free-opencv-guest-diagnostic.v1';status='fail';harnessError=$_.Exception.Message;temporalLinkageClaimed=$false;releaseEvidence=$false}|ConvertTo-Json|Set-Content (Join-Path $OutputRoot 'model-free-opencv-guest-diagnostic.json') -Encoding utf8;exit 2}
